def process(roman_cities) -> pd.DataFrame:
    # The Primary Key column starts with "Hanson2016_" suggesting a single source dataset
    # But "Select Bibliography" contains the actual sources used
    # Let's parse all unique sources from the Select Bibliography column

    sources = set()
    for entry in roman_cities['Select Bibliography'].dropna():
        # Sources are separated by semicolons
        parts = entry.split(';')
        for part in parts:
            src = part.strip().rstrip('.')
            if src:
                sources.add(src)

    return pd.DataFrame({'unique_source': sorted(sources), 'count': [1]*len(sources)})
